const promptReferenceStackStyles = "/* Reference-image uploader: cropped thumbnails, stable stacking, precise removal. */\n\n.prompt-dock .prompt-dock-prompt textarea {\n  padding-top: 0 !important;\n  font-size: 14px !important;\n}\n\n.prompt-dock .prompt-dock-reference-zone {\n  --reference-motion: 360ms var(--glass-motion-ease);\n  transition:\n    flex-basis var(--reference-motion),\n    filter 220ms ease;\n}\n\n.prompt-dock .prompt-dock-reference-stack {\n  cursor: default;\n}\n\n.prompt-dock .prompt-dock-reference-stack.is-empty {\n  cursor: pointer;\n}\n\n.prompt-dock .prompt-dock-reference-cards {\n  pointer-events: auto;\n}\n\n.prompt-dock .prompt-dock-reference-card {\n  overflow: visible;\n  isolation: isolate;\n  will-change: transform;\n  transition:\n    transform var(--reference-motion),\n    box-shadow 220ms ease,\n    filter 220ms ease;\n}\n\n.prompt-dock .prompt-dock-reference-card > img {\n  display: block;\n  width: 100%;\n  height: 100%;\n  border-radius: inherit;\n  object-fit: cover;\n  user-select: none;\n  -webkit-user-drag: none;\n}\n\n.prompt-dock .prompt-dock-reference-remove {\n  position: absolute;\n  z-index: 2;\n  top: -8px;\n  right: -8px;\n  width: 21px;\n  height: 21px;\n  padding: 0;\n  border: 1px solid rgba(255, 255, 255, 0.68);\n  border-radius: 50%;\n  background: rgba(42, 46, 55, 0.94);\n  color: #fff;\n  box-shadow: 0 5px 13px rgba(18, 21, 28, 0.2);\n  opacity: 0;\n  transform: scale(0.72);\n  pointer-events: none;\n  transition:\n    opacity 150ms ease,\n    transform 220ms var(--glass-motion-ease),\n    background 150ms ease;\n}\n\n.prompt-dock .prompt-dock-reference-remove::before,\n.prompt-dock .prompt-dock-reference-remove::after {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 9px;\n  height: 1.4px;\n  border-radius: 999px;\n  background: currentColor;\n}\n\n.prompt-dock .prompt-dock-reference-remove::before {\n  transform: translate(-50%, -50%) rotate(45deg);\n}\n\n.prompt-dock .prompt-dock-reference-remove::after {\n  transform: translate(-50%, -50%) rotate(-45deg);\n}\n\n.prompt-dock .prompt-dock-reference-remove:hover {\n  background: rgba(28, 31, 38, 0.98);\n  transform: scale(1.08);\n}\n\n.prompt-dock .prompt-dock-reference-card:hover,\n.prompt-dock .prompt-dock-reference-card:focus-within {\n  z-index: 30 !important;\n}\n\n.prompt-dock .prompt-dock-reference-card:hover .prompt-dock-reference-remove,\n.prompt-dock .prompt-dock-reference-card:focus-within .prompt-dock-reference-remove {\n  opacity: 1;\n  transform: scale(1);\n  pointer-events: auto;\n}\n\n.prompt-dock .prompt-dock-reference-add {\n  cursor: pointer;\n}\n\n.prompt-dock .prompt-dock-reference-add > span,\n.prompt-dock .prompt-dock-reference-empty-card > span {\n  position: absolute;\n  inset: 0;\n}\n\n.prompt-dock .prompt-dock-reference-add > span::before,\n.prompt-dock .prompt-dock-reference-add > span::after,\n.prompt-dock .prompt-dock-reference-empty-card > span::before,\n.prompt-dock .prompt-dock-reference-empty-card > span::after {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 12px;\n  height: 1.35px;\n  border-radius: 999px;\n  background: currentColor;\n  transform: translate(-50%, -50%);\n}\n\n.prompt-dock .prompt-dock-reference-add > span::after,\n.prompt-dock .prompt-dock-reference-empty-card > span::after {\n  transform: translate(-50%, -50%) rotate(90deg);\n}\n\n.prompt-dock .prompt-dock-reference-stack:hover .prompt-dock-reference-add,\n.prompt-dock .prompt-dock-reference-add:hover,\n.prompt-dock .prompt-dock-reference-add:focus-visible {\n  background: #fff;\n  transform: scale(1.08);\n}\n\n.prompt-dock .prompt-dock-reference-add:focus-visible,\n.prompt-dock .prompt-dock-reference-remove:focus-visible,\n.prompt-dock .prompt-dock-reference-stack.is-empty:focus-visible {\n  outline: 2px solid rgba(113, 104, 238, 0.42);\n  outline-offset: 3px;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-card,\n.prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-card {\n  transform:\n    translateX(var(--reference-open-x))\n    rotate(var(--reference-open-rotate));\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-card:hover,\n.prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-card:focus-within {\n  transform:\n    translateX(var(--reference-open-x))\n    translateY(-3px)\n    rotate(0deg)\n    scale(1.04);\n  box-shadow: 0 13px 28px rgba(24, 28, 38, 0.18);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .prompt-dock .prompt-dock-reference-zone,\n  .prompt-dock .prompt-dock-reference-stack,\n  .prompt-dock .prompt-dock-reference-card,\n  .prompt-dock .prompt-dock-reference-add,\n  .prompt-dock .prompt-dock-reference-remove {\n    transition-duration: 1ms !important;\n  }\n}\n\n@media (hover: none) {\n  .prompt-dock .prompt-dock-reference-card:focus-within .prompt-dock-reference-remove {\n    opacity: 1;\n    pointer-events: auto;\n  }\n}\n\n\n/* Uploaded state: the thumbnail replaces the empty upload tile. */\n.prompt-dock .prompt-dock-reference-zone.has-images {\n  --reference-thumb-width: 64px;\n  --reference-thumb-height: 70px;\n  --reference-thumb-radius: 14px;\n  overflow: visible;\n  border-radius: 0;\n  background: transparent;\n  box-shadow: none;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-tilt {\n  position: relative;\n  display: block;\n  width: 100%;\n  height: 100%;\n  padding: 0;\n  overflow: visible;\n  border-radius: 0;\n  background: transparent !important;\n  box-shadow: none !important;\n  transform: none !important;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-upload-label {\n  display: none;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-stack {\n  position: relative;\n  display: block;\n  width: 64px;\n  height: 70px;\n  margin: 0 auto;\n  overflow: visible;\n  border: 0;\n  background: transparent;\n  box-shadow: none;\n  filter: none;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-cards {\n  position: absolute;\n  inset: 0;\n  overflow: visible;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-card {\n  position: absolute;\n  display: block;\n  box-sizing: border-box;\n  left: 0;\n  top: 0;\n  width: var(--reference-thumb-width) !important;\n  min-width: var(--reference-thumb-width) !important;\n  max-width: var(--reference-thumb-width) !important;\n  height: var(--reference-thumb-height) !important;\n  min-height: var(--reference-thumb-height) !important;\n  max-height: var(--reference-thumb-height) !important;\n  flex: 0 0 var(--reference-thumb-width);\n  aspect-ratio: auto !important;\n  padding: 0;\n  overflow: visible;\n  border: 0;\n  border-radius: var(--reference-thumb-radius);\n  background: transparent;\n  box-shadow: 0 4px 11px rgba(24, 28, 38, 0.12);\n  transform:\n    translate(var(--reference-stack-x), var(--reference-stack-y))\n    rotate(var(--reference-stack-rotate));\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-card > img {\n  position: absolute !important;\n  inset: 0 !important;\n  display: block;\n  box-sizing: border-box;\n  width: 100% !important;\n  min-width: 100% !important;\n  max-width: 100% !important;\n  height: 100% !important;\n  min-height: 100% !important;\n  max-height: 100% !important;\n  aspect-ratio: auto !important;\n  border: 0;\n  border-radius: var(--reference-thumb-radius);\n  background: transparent;\n  object-fit: cover !important;\n  object-position: 50% 50% !important;\n  clip-path: inset(0 round var(--reference-thumb-radius));\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-add {\n  right: -6px;\n  bottom: -1px;\n  width: 21px;\n  height: 21px;\n  border: 1px solid rgba(39, 43, 53, 0.08) !important;\n  border-radius: 50% !important;\n  background: rgba(255, 255, 255, 0.96) !important;\n  box-shadow: 0 4px 11px rgba(24, 28, 38, 0.16) !important;\n  transform: none;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images:hover,\n.prompt-dock .prompt-dock-reference-zone.has-images:focus-within {\n  flex-basis: var(--reference-zone-open-width);\n  width: var(--reference-zone-open-width);\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-stack,\n.prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-stack {\n  width: var(--reference-open-width);\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-add,\n.prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-add {\n  right: -8px;\n}\n\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-add:hover,\n.prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-add:focus-visible {\n  background: #fff !important;\n  transform: scale(1.08);\n}\n\n@media (max-width: 680px) {\n  .prompt-dock .prompt-dock-reference-zone.has-images {\n    --reference-thumb-width: 56px;\n    --reference-thumb-height: 62px;\n    --reference-thumb-radius: 12px;\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-stack {\n    width: 56px;\n    height: 62px;\n    margin-top: 0;\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-card {\n    left: 0;\n    top: 0;\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images .prompt-dock-reference-add {\n    width: 19px;\n    height: 19px;\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images:hover,\n  .prompt-dock .prompt-dock-reference-zone.has-images:focus-within {\n    flex-basis: min(var(--reference-zone-open-width), 148px);\n    width: min(var(--reference-zone-open-width), 148px);\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-stack,\n  .prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-stack {\n    width: min(var(--reference-open-width), 142px);\n  }\n\n  .prompt-dock .prompt-dock-reference-zone.has-images:hover .prompt-dock-reference-card,\n  .prompt-dock .prompt-dock-reference-zone.has-images:focus-within .prompt-dock-reference-card {\n    transform:\n      translateX(var(--reference-open-mobile-x))\n      rotate(var(--reference-open-rotate));\n  }\n}\n\n/* Match the empty uploader's hover angle to the category mini card. */\n.prompt-dock .prompt-dock-reference-zone.is-empty:hover .prompt-dock-reference-tilt {\n  transform: rotate(-8deg);\n}\n";

const ensurePromptReferenceStackStyles = () => {
  if (document.getElementById("prompt-reference-stack-runtime-styles")) return;

  const style = document.createElement("style");
  style.id = "prompt-reference-stack-runtime-styles";
  style.textContent = promptReferenceStackStyles;
  document.head.append(style);
};

const syncStyleControlLabel = () => {
  document
    .querySelectorAll(
      ".prompt-dock-options .is-style-selector .prompt-dock-select-trigger",
    )
    .forEach((styleControl) => {
      const selector = styleControl.closest(".is-style-selector");
      const hasSelectedTheme =
        selector?.classList.contains("has-theme-play") ||
        Boolean(styleControl.querySelector(".prompt-dock-theme-thumb"));

      // React owns the selected gameplay name and accessible label. Only keep
      // the generic fallback label in sync while no gameplay is selected.
      if (hasSelectedTheme) return;

      const label = styleControl.querySelector("strong");
      if (label && label.textContent !== "风格") {
        label.textContent = "风格";
      }

      if (styleControl.getAttribute("aria-label") !== "风格") {
        styleControl.setAttribute("aria-label", "风格");
      }
    });
};

const syncApprovedStyleIcon = () => {
  document
    .querySelectorAll(
      ".prompt-dock-select.is-style-selector .prompt-dock-control-icon",
    )
    .forEach((slot) => {
      const approvedIcon = slot.querySelector(
        'img[data-approved-style-icon="true"]',
      );
      if (approvedIcon && slot.childElementCount === 1) return;

      const img = document.createElement("img");
      img.className = "creative-panel-icon prompt-dock-approved-style-icon";
      img.src = panelIcons.style;
      img.alt = "";
      img.setAttribute("aria-hidden", "true");
      img.setAttribute("data-approved-style-icon", "true");
      img.draggable = false;
      slot.replaceChildren(img);
    });
};

const WORKBENCH_COMPOSER_ICON_TARGETS = [
  [".prompt-dock-select.is-model-selector .prompt-dock-control-icon", "model"],
  [".prompt-dock-select.is-generation-selector .prompt-dock-control-icon", "size"],
];

const swapWorkbenchComposerIcons = () => {
  document
    .querySelectorAll(".creative-composer-surface.is-workbench-prompt-dock")
    .forEach((surface) => {
      WORKBENCH_COMPOSER_ICON_TARGETS.forEach(([selector, name]) => {
        surface.querySelectorAll(selector).forEach((slot) => {
          if (slot.querySelector(".creative-panel-icon")) return;
          slot.querySelectorAll("svg").forEach((svg) => svg.remove());
          const img = document.createElement("img");
          img.className = "creative-panel-icon";
          img.src = panelIcons[name];
          img.alt = "";
          img.setAttribute("aria-hidden", "true");
          img.draggable = false;
          img.style.cssText = "display:block;width:18px;height:18px;";
          slot.append(img);
        });
      });
    });
};

const syncComposerEnhancements = () => {
  syncStyleControlLabel();
  syncApprovedStyleIcon();
  swapWorkbenchComposerIcons();
};

const observer = new MutationObserver(syncComposerEnhancements);

const startPromptDockRefinements = () => {
  ensurePromptReferenceStackStyles();
  syncComposerEnhancements();
  observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
  });
};

if (document.body) {
  startPromptDockRefinements();
} else {
  window.addEventListener("DOMContentLoaded", startPromptDockRefinements, {
    once: true,
  });
}

