const promptCategoryNames = [
  "T恤",
  "卫衣",
  "帆布包",
  "马克杯",
  "3D打印",
  "冰箱贴",
];

let isPromptCategoryUnselected = true;
let hasPromptCategoryDefaultSynced = false;

const ensureDefaultPromptCategoryCardStyles = () => {
  if (document.getElementById("default-prompt-category-card-styles")) return;
  const style = document.createElement("style");
  style.id = "default-prompt-category-card-styles";
  const componentScopedStyles = defaultPromptCategoryCardStyles.replaceAll(
    "html.is-category-unselected .prompt-dock-shell .prompt-dock-editor-category\n  .is-category-selector",
    ".prompt-dock-editor-category\n  .is-category-selector.is-category-unselected",
  );
  style.textContent =
    defaultPromptCategoryCardStyles + "\n" + componentScopedStyles;
  document.head.append(style);
};

const getPromptCategoryTrigger = (scope = document) =>
  scope.querySelector(
    ".prompt-dock-editor-category .is-category-selector .prompt-dock-select-trigger",
  );

let promptCategoryRequiredTip = null;
let promptCategoryRequiredTipTimer = 0;

const hidePromptCategoryRequiredTip = () => {
  window.clearTimeout(promptCategoryRequiredTipTimer);
  promptCategoryRequiredTip?.remove();
  promptCategoryRequiredTip = null;
};

const showPromptCategoryRequiredTip = (trigger) => {
  if (!trigger) return;
  hidePromptCategoryRequiredTip();

  const tip = document.createElement("div");
  tip.className = "prompt-category-required-tip";
  tip.textContent = "还未选择定制品类";
  tip.setAttribute("role", "status");
  document.body.append(tip);

  const rect = trigger.getBoundingClientRect();
  const tipRect = tip.getBoundingClientRect();
  const left = Math.min(
    window.innerWidth - tipRect.width - 12,
    Math.max(12, rect.left + rect.width / 2 - tipRect.width / 2),
  );
  const top = Math.max(12, rect.top - tipRect.height - 10);
  tip.style.left = `${left}px`;
  tip.style.top = `${top}px`;
  requestAnimationFrame(() => tip.classList.add("is-visible"));

  promptCategoryRequiredTip = tip;
  promptCategoryRequiredTipTimer = window.setTimeout(
    hidePromptCategoryRequiredTip,
    1800,
  );
};

const readCategoryName = (element) => {
  const source = [
    element?.textContent || "",
    element?.getAttribute?.("aria-label") || "",
  ].join(" ");
  return promptCategoryNames.find((name) => source.includes(name)) || "";
};

const syncPromptCategoryMenuSelectionState = () => {
  if (!isPromptCategoryUnselected) return;

  document
    .querySelectorAll("#prompt-dock-menu-category [role='option']")
    .forEach((choice) => {
      if (choice.getAttribute("aria-selected") !== "false") {
        choice.setAttribute("aria-selected", "false");
      }
      if (choice.classList.contains("is-selected")) {
        choice.classList.remove("is-selected");
      }
    });
};

const syncDefaultPromptCategoryCard = () => {
  if (!isPromptCategoryUnselected) return;
  document.documentElement.classList.add("is-category-unselected");
  syncPromptCategoryMenuSelectionState();

  const trigger = getPromptCategoryTrigger();
  if (!trigger) return;

  if (hasPromptCategoryDefaultSynced) {
    const selectedCategoryName = readCategoryName(trigger);
    if (selectedCategoryName) {
      resolvePromptCategorySelection(selectedCategoryName);
      return;
    }
  }

  const label = trigger.querySelector("strong");
  if (label && label.textContent !== "品类") {
    label.textContent = "品类";
  }
  if (trigger.getAttribute("aria-label") !== "选择品类") {
    trigger.setAttribute("aria-label", "选择品类");
  }
  hasPromptCategoryDefaultSynced = true;
};

const promptCategoryMotion = {
  exit: 170,
  enter: 520,
};

let promptCategoryExitTimer = 0;
let promptCategoryEnterTimer = 0;
let promptCategoryTransitionTarget = "";
let promptCategoryExitSnapshot = null;

const clearPromptCategoryExitSnapshot = () => {
  promptCategoryExitSnapshot
    ?.closest(".prompt-category-exit-overlay")
    ?.remove();
  promptCategoryExitSnapshot?.remove();
  promptCategoryExitSnapshot = null;
  document.documentElement.classList.remove("is-category-card-switching");
};

const clearPromptCategoryMotion = () => {
  window.clearTimeout(promptCategoryExitTimer);
  window.clearTimeout(promptCategoryEnterTimer);
  clearPromptCategoryExitSnapshot();
  document.documentElement.classList.remove("is-category-card-entering");
  getPromptCategoryTrigger()?.classList.remove(
    "is-category-card-exiting",
    "is-category-card-entering",
  );
};

const applyPromptCategorySelection = (categoryName = "") => {
  hidePromptCategoryRequiredTip();
  isPromptCategoryUnselected = false;
  document.documentElement.classList.remove("is-category-unselected");

  const trigger = getPromptCategoryTrigger();
  trigger?.classList.remove("is-category-card-exiting");

  if (!categoryName) return;
  const label = trigger?.querySelector("strong");
  if (label) label.textContent = categoryName;
  trigger?.setAttribute("aria-label", `品类：${categoryName}`);
};

const createPromptCategoryExitSnapshot = (trigger) => {
  if (!trigger) return null;

  const rect = trigger.getBoundingClientRect();
  if (!rect.width || !rect.height) return null;

  const overlay = document.createElement("div");
  overlay.className =
    "prompt-category-exit-overlay prompt-dock-editor-category";
  overlay.style.left = `${rect.left}px`;
  overlay.style.top = `${rect.top}px`;
  overlay.style.width = `${rect.width}px`;
  overlay.style.height = `${rect.height}px`;

  const selector = document.createElement("div");
  selector.className = "prompt-dock-select is-category-selector";

  const snapshot = trigger.cloneNode(true);
  snapshot.classList.remove(
    "is-category-card-entering",
    "is-category-card-exiting",
  );
  snapshot.classList.add("is-category-card-exit-snapshot");
  snapshot.setAttribute("aria-hidden", "true");
  snapshot.removeAttribute("aria-controls");
  snapshot.removeAttribute("aria-expanded");
  snapshot.tabIndex = -1;

  selector.append(snapshot);
  overlay.append(selector);
  document.body.append(overlay);
  return snapshot;
};

const resolvePromptCategorySelection = (
  categoryName = "",
  { animate = true } = {},
) => {
  if (!categoryName) return;

  const trigger = getPromptCategoryTrigger();
  const currentCategoryName = isPromptCategoryUnselected
    ? ""
    : readCategoryName(trigger);

  if (
    !promptCategoryTransitionTarget &&
    currentCategoryName === categoryName
  ) {
    return;
  }

  if (promptCategoryTransitionTarget === categoryName) return;

  const reduceMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (!animate || reduceMotion || !trigger) {
    clearPromptCategoryMotion();
    applyPromptCategorySelection(categoryName);
    promptCategoryTransitionTarget = "";
    return;
  }

  clearPromptCategoryMotion();
  promptCategoryTransitionTarget = categoryName;
  promptCategoryExitSnapshot = createPromptCategoryExitSnapshot(trigger);

  if (!promptCategoryExitSnapshot) {
    applyPromptCategorySelection(categoryName);
    promptCategoryTransitionTarget = "";
    return;
  }

  document.documentElement.classList.add("is-category-card-switching");
  void promptCategoryExitSnapshot.offsetWidth;
  promptCategoryExitSnapshot.classList.add("is-category-card-exiting");

  promptCategoryExitTimer = window.setTimeout(() => {
    applyPromptCategorySelection(categoryName);
    clearPromptCategoryExitSnapshot();

    const selectedTrigger = getPromptCategoryTrigger();
    if (!selectedTrigger) {
      promptCategoryTransitionTarget = "";
      return;
    }

    selectedTrigger.classList.remove("is-category-card-exiting");
    document.documentElement.classList.add("is-category-card-entering");
    void selectedTrigger.offsetWidth;
    selectedTrigger.classList.add("is-category-card-entering");

    promptCategoryEnterTimer = window.setTimeout(() => {
      document.documentElement.classList.remove("is-category-card-entering");
      getPromptCategoryTrigger()?.classList.remove(
        "is-category-card-entering",
      );
      promptCategoryTransitionTarget = "";
    }, promptCategoryMotion.enter);
  }, promptCategoryMotion.exit);
};

const isCategoryMenuChoice = (target) => {
  const choice = target.closest(
    "#prompt-dock-menu-category [role='option'], #prompt-dock-menu-category button",
  );
  if (!choice) return null;
  const categoryName = readCategoryName(choice);
  return categoryName ? { choice, categoryName } : null;
};

const handleDefaultPromptCategoryPointerDown = (event) => {
  if (!(event.target instanceof Element)) return;

  const menuChoice = isCategoryMenuChoice(event.target);
  if (menuChoice) {
    resolvePromptCategorySelection(menuChoice.categoryName);
  }
};

const handleDefaultPromptCategoryClick = (event) => {
  if (!(event.target instanceof Element)) return;

  const menuChoice = isCategoryMenuChoice(event.target);
  if (menuChoice) {
    const trigger = getPromptCategoryTrigger();
    if (!trigger?.classList.contains("is-category-card-exiting")) {
      resolvePromptCategorySelection(menuChoice.categoryName);
    }
    return;
  }

  const customizeButton = event.target.closest("button");
  if (customizeButton?.textContent?.trim() === "立即定制") {
    const categoryName = readCategoryName(customizeButton.parentElement);
    resolvePromptCategorySelection(categoryName, { animate: false });
    return;
  }

  const generateButton = event.target.closest(".prompt-dock-generate");
  if (generateButton) {
    const promptDock = generateButton.closest(".prompt-dock");
    const trigger = getPromptCategoryTrigger(promptDock || document);
    const selectedCategoryName = readCategoryName(trigger);

    // The composer can be remounted independently from the page-level runtime.
    // Treat the category card beside this generate button as the source of truth,
    // instead of relying on the shared initial-state flag.
    if (selectedCategoryName) {
      isPromptCategoryUnselected = false;
      document.documentElement.classList.remove("is-category-unselected");
      hidePromptCategoryRequiredTip();
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    showPromptCategoryRequiredTip(trigger);

    // Open the menu through the same category trigger the user would click,
    // so React computes exactly the same anchor position in the Agent dock.
    if (trigger?.getAttribute("aria-expanded") !== "true") {
      trigger?.click();
    }
  }
};

const defaultPromptCategoryObserver = new MutationObserver(
  syncDefaultPromptCategoryCard,
);

const startDefaultPromptCategoryCard = () => {
  ensureDefaultPromptCategoryCardStyles();
  syncDefaultPromptCategoryCard();
  document.addEventListener(
    "pointerdown",
    handleDefaultPromptCategoryPointerDown,
    true,
  );
  document.addEventListener(
    "click",
    handleDefaultPromptCategoryClick,
    true,
  );
  defaultPromptCategoryObserver.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["aria-label", "aria-selected", "class"],
  });
};

document.documentElement.classList.add("is-category-unselected");

if (document.body) {
  startDefaultPromptCategoryCard();
} else {
  window.addEventListener(
    "DOMContentLoaded",
    startDefaultPromptCategoryCard,
    { once: true },
  );
}
